===== src/payments/service.js =====
     1	'use strict';
     2	
     3	const { invalid, conflict, notFound } = require('../lib/errors');
     4	const { isAmount } = require('../lib/money');
     5	const { getProvider } = require('./providers');
     6	
     7	function createPaymentService({ store, orders, provider = 'manual' }) {
     8	  const gateway = getProvider(provider);
     9	
    10	  function orderTotalCents(order) {
    11	    let cents = 0;
    12	    for (const item of order.items) cents += Math.round(item.unitPrice * 100) * item.quantity;
    13	    return cents;
    14	  }
    15	
    16	  function capture(user, { orderId, amount }) {
    17	    if (typeof orderId !== 'string' || orderId === '') throw invalid('orderId is required');
    18	    if (!isAmount(amount)) throw invalid('amount must be a positive amount with at most two decimals');
    19	    const order = orders.getOwned(user, orderId);
    20	    if (order.status !== 'pending') throw conflict('order is not awaiting payment');
    21	    if (Math.round(amount * 100) !== orderTotalCents(order)) throw invalid('amount does not match the order total');
    22	    const charge = gateway.charge({ amount, reference: order.id });
    23	    const payment = store.insert('payments', {
    24	      orderId: order.id,
    25	      userId: user.id,
    26	      amount,
    27	      status: charge.status,
    28	      providerReference: charge.id,
    29	      createdAt: new Date().toISOString(),
    30	    });
    31	    orders.markPaid(order.id, payment.id);
    32	    return payment;
    33	  }
    34	
    35	  function get(user, id) {
    36	    const payment = store.get('payments', id);
    37	    if (!payment || (user.role !== 'admin' && payment.userId !== user.id)) throw notFound('payment not found');
    38	    return payment;
    39	  }
    40	
    41	  return { capture, get };
    42	}
    43	
    44	module.exports = { createPaymentService };
