const CENTS_PER_UNIT = 100;

function isAmount(value) {
  return typeof value === 'number'
    && Number.isFinite(value)
    && value > 0
    && Math.abs(value * CENTS_PER_UNIT - Math.round(value * CENTS_PER_UNIT)) < 1e-6;
