  // scrypt work as a known one and cannot be told apart by response time.
  const absentSalt = crypto.randomBytes(16).toString('hex');
  const absentHash = hashPassword(crypto.randomBytes(32).toString('hex'), absentSalt);

  function register({ email, password, name }, role = 'customer') {
