test('an order is hidden from customers who do not own it', async (t) => {
  const { call, signUp } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const bob = await signUp('bob@example.com');
  const order = (await call('POST', '/orders', { token: alice, body: { items: ITEMS } })).body;
  assert.equal((await call('GET', `/orders/${order.id}`, { token: bob })).status, 404);
});

test('an order total is exact to the cent', async (t) => {
  const { call, signUp } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const order = (await call('POST', '/orders', {
    token: alice,
    body: { items: [{ sku: 'DIME-1', unitPrice: 0.1, quantity: 3 }, { sku: 'DIME-2', unitPrice: 0.2, quantity: 1 }] },
  })).body;
  assert.equal(order.total, 0.5);
  assert.equal((await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount: 0.5 } })).status, 201);
});

test('a shipped or delivered order can no longer be cancelled', async (t) => {
  const { call, signUp, adminToken } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const order = (await call('POST', '/orders', { token: alice, body: { items: ITEMS } })).body;
  await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount: 30 } });
  await call('POST', `/orders/${order.id}/ship`, { token: adminToken });
  assert.equal((await call('POST', `/orders/${order.id}/cancel`, { token: alice })).status, 409);
  await call('POST', `/orders/${order.id}/deliver`, { token: adminToken });
  assert.equal((await call('POST', `/orders/${order.id}/cancel`, { token: alice })).status, 409);
});

test('a page reports every page needed to show its items', async (t) => {
  const { call, signUp } = await startApp(t);
  const alice = await signUp('alice@example.com');
  for (let i = 0; i < 12; i += 1) {
    await call('POST', '/orders', { token: alice, body: { items: ITEMS } });
  }
  const first = await call('GET', '/orders?pageSize=5', { token: alice });
  assert.equal(first.body.total, 12);
  assert.equal(first.body.totalPages, 3);
  const last = await call('GET', '/orders?pageSize=5&page=3', { token: alice });
  assert.equal(last.body.items.length, 2);
});
